SELECT ib_income_band_sk, hd_buy_potential, SUM(cs_ext_sales_price) AS total_sales, AVG(cs_ext_sales_price) AS avg_sales FROM catalog_sales JOIN household_demographics ON catalog_sales.cs_bill_hdemo_sk = household_demographics.hd_demo_sk JOIN income_band ON household_demographics.hd_income_band_sk = income_band.ib_income_band_sk WHERE ib_lower_bound >= 130001 AND ib_upper_bound <= 50000 GROUP BY ib_income_band_sk, hd_buy_potential ORDER BY total_sales DESC LIMIT 1000
